#define HRPWM_MINDBCFG_SELBLOCKA   0x8U         // BLOCK signal source select on PWMA
#define HRPWM_MINDBCFG_SELA_S      4U
#define HRPWM_MINDBCFG_SELA_M      0xF0U        // Reference source select on PWMA min dead band
                                                // logic.
#define HRPWM_MINDBCFG_POLSELA     0x100U       // Select signal for the AND OR logic of PWMA
#define HRPWM_MINDBCFG_ENABLEB     0x10000U     // Minimum dead band logic enable on PWMB
#define HRPWM_MINDBCFG_INVERTB     0x40000U     // Invert the selected reference signal on PWMB
#define HRPWM_MINDBCFG_SELBLOCKB   0x80000U     // BLOCK signal source select on PWMB
#define HRPWM_MINDBCFG_SELB_S      20U
#define HRPWM_MINDBCFG_SELB_M      0xF00000U    // Reference source select on PWMB min dead band
                                                // logic.
#define HRPWM_MINDBCFG_POLSELB     0x1000000U   // Select signal for the AND OR logic of PWMB

//*************************************************************************************************
//
// The following are defines for the bit fields in the MINDBDLY register
//
//*************************************************************************************************
#define HRPWM_MINDBDLY_DELAYA_S   0U
#define HRPWM_MINDBDLY_DELAYA_M   0xFFFFU       // Minimum dead band delay on PWMA
#define HRPWM_MINDBDLY_DELAYB_S   16U
#define HRPWM_MINDBDLY_DELAYB_M   0xFFFF0000U   // Minimum dead band delay on PWMB

//*************************************************************************************************
//
// The following are defines for the bit fields in the LUTCTLA register
//
//*************************************************************************************************
#define HRPWM_LUTCTLA_BYPASS      0x1U        // Bypass LUTA
#define HRPWM_LUTCTLA_SELXBAR_S   4U
#define HRPWM_LUTCTLA_SELXBAR_M   0xF0U       // ICSS XBAR select
#define HRPWM_LUTCTLA_LUTDEC0     0x10000U    // LUT output PWMA value on decoding 0
#define HRPWM_LUTCTLA_LUTDEC1     0x20000U    // LUT output PWMA value on decoding 1
#define HRPWM_LUTCTLA_LUTDEC2     0x40000U    // LUT output PWMA value on decoding 2
#define HRPWM_LUTCTLA_LUTDEC3     0x80000U    // LUT output PWMA value on decoding 3
#define HRPWM_LUTCTLA_LUTDEC4     0x100000U   // LUT output PWMA value on decoding 4
#define HRPWM_LUTCTLA_LUTDEC5     0x200000U   // LUT output PWMA value on decoding 5
#define HRPWM_LUTCTLA_LUTDEC6     0x400000U   // LUT output PWMA value on decoding 6
#define HRPWM_LUTCTLA_LUTDEC7     0x800000U   // LUT output PWMA value on decoding 7

//*************************************************************************************************
//
// The following are defines for the bit fields in the LUTCTLB register
//
//*************************************************************************************************
#define HRPWM_LUTCTLB_BYPASS      0x1U        // Bypass LUTB
#define HRPWM_LUTCTLB_SELXBAR_S   4U
#define HRPWM_LUTCTLB_SELXBAR_M   0xF0U       // ICSS XBAR select
#define HRPWM_LUTCTLB_LUTDEC0     0x10000U    // LUT output PWMB value on decoding 0
#define HRPWM_LUTCTLB_LUTDEC1     0x20000U    // LUT output PWMB value on decoding 1
#define HRPWM_LUTCTLB_LUTDEC2     0x40000U    // LUT output PWMB value on decoding 2
#define HRPWM_LUTCTLB_LUTDEC3     0x80000U    // LUT output PWMB value on decoding 3
#define HRPWM_LUTCTLB_LUTDEC4     0x100000U   // LUT output PWMB value on decoding 4
#define HRPWM_LUTCTLB_LUTDEC5     0x200000U   // LUT output PWMB value on decoding 5
#define HRPWM_LUTCTLB_LUTDEC6     0x400000U   // LUT output PWMB value on decoding 6
#define HRPWM_LUTCTLB_LUTDEC7     0x800000U   // LUT output PWMB value on decoding 7



#endif

