#define LIN_SCIGCR1_STOP            0x10U        // SCI number of stop bits
#define LIN_SCIGCR1_CLK_COMMANDER   0x20U        // LIN Commander/Responder selection and SCI clock
                                                 // enable
#define LIN_SCIGCR1_LINMODE         0x40U        // LIN Mode enable/disable
