#define USB_HOST_PWRFLT_LOW     0x00000010UL
#define USB_HOST_PWRFLT_HIGH    0x00000030UL
#define USB_HOST_PWRFLT_EP_NONE 0x00000000UL
#define USB_HOST_PWRFLT_EP_TRI  0x00000140UL
